<?php
namespace App\Http\Controllers;
use App\Models\Wedding;
use App\Models\WeddingAudit;
use App\Models\WeddingFinanceItem;
use Illuminate\Http\Request;
use Inertia\Inertia;
class WeddingFinanceController extends Controller { private function authorizeFinance(Request $request, Wedding $wedding): void { $member = $request->user()->weddingMemberships()->where('wedding_id', $wedding->id)->first(); abort_unless($request->user()->role === 'admin' || ($member && data_get($member->permissions, 'view_finance')), 403); } public function index(Request $request, Wedding $wedding) { $this->authorizeFinance($request, $wedding); $manage = in_array($request->user()->role, ['admin','finance'], true); $items = $wedding->financeItems()->when(!$manage, fn ($query) => $query->where('visible_to_couple', true))->with('attachments')->withSum('payments as paid_amount', 'amount')->latest()->get(); return Inertia::render('Weddings/Finance', ['wedding' => $wedding, 'items' => $items, 'quotes' => $manage ? $wedding->vendorQuotes()->latest()->get() : [], 'canManage' => $manage]); } public function storeItem(Request $request, Wedding $wedding) { $this->authorizeFinance($request, $wedding); abort_unless(in_array($request->user()->role, ['admin','finance'], true), 403); $item = $wedding->financeItems()->create($request->validate(['type' => ['required','in:charge,cost'], 'description' => ['required','string','max:180'], 'amount' => ['required','numeric','min:0'], 'due_date' => ['nullable','date'], 'visible_to_couple' => ['boolean'], 'notes' => ['nullable','string','max:2000']])); WeddingAudit::create(['wedding_id' => $wedding->id,'actor_id' => $request->user()->id,'action' => 'finance.item_created','subject_type' => get_class($item),'subject_id' => $item->id,'after' => $item->toArray()]); return back()->with('success','Concepto financiero registrado.'); } public function storeQuote(Request $request, Wedding $wedding) { $this->authorizeFinance($request, $wedding); abort_unless(in_array($request->user()->role, ['admin','finance'], true), 403); $quote = $wedding->vendorQuotes()->create($request->validate(['vendor_name' => ['required','string','max:180'], 'title' => ['required','string','max:180'], 'details' => ['nullable','string','max:5000'], 'amount' => ['required','numeric','min:0'], 'valid_until' => ['nullable','date']])); WeddingAudit::create(['wedding_id' => $wedding->id,'actor_id' => $request->user()->id,'action' => 'finance.quote_created','subject_type' => get_class($quote),'subject_id' => $quote->id,'after' => $quote->toArray()]); return back()->with('success','Cotización registrada.'); } public function storePayment(Request $request, Wedding $wedding, WeddingFinanceItem $item) { $this->authorizeFinance($request, $wedding); abort_unless(in_array($request->user()->role, ['admin','finance'], true) && $item->wedding_id === $wedding->id, 403); $data = $request->validate(['amount' => ['required','numeric','min:0.01'], 'paid_at' => ['required','date'], 'method' => ['required','in:cash,transfer,card,other'], 'reference' => ['nullable','string','max:180']]); $paid = (float) $item->payments()->sum('amount'); abort_if($paid + $data['amount'] > (float) $item->amount, 422, 'El pago excede el importe del concepto.'); $payment = $item->payments()->create([...$data, 'recorded_by' => $request->user()->id]); if ($paid + $data['amount'] >= (float) $item->amount) $item->update(['status' => 'paid']); WeddingAudit::create(['wedding_id' => $wedding->id,'actor_id' => $request->user()->id,'action' => 'finance.payment_recorded','subject_type' => get_class($payment),'subject_id' => $payment->id,'after' => $payment->toArray()]); return back()->with('success','Pago registrado.'); } }
